def synthetic_snapshot(root: Path) -> Path:
    """Complete matrix with sentinel values, never an actual workload oracle."""
    files: dict[str, bytes] = {}
    rows: list[dict[str, Any]] = []
    for component in v.REQUIRED_COMPONENTS:
        files[f"components/{component}"] = b"synthetic component\n"
    for n in range(3):
        model = {"id": f"synthetic-{n}", "model": {}, "shape": {}, "sources": ["synthetic"]}
        files[f"model_shapes/{model['id']}.json"] = v.canonical(model)
        for component in v.REQUIRED_COMPONENTS:
            for precision in v.component_precisions(component):
                for tp in (1, 8):
                    for query in v.QUERIES:
                        rows.append(
                            {
                                "id": str(len(rows)),
                                "model_id": model["id"],
                                "model": {},
                                "model_shape": {},
                                "model_sources": ["synthetic"],
                                "rk_sha": v.PIN,
                                "counts_scope": "replica",
                                "duration_scope": "one_tp_rank_no_collectives",
                                "duration_method": str(query["phase"]) + "_s",
                                "duration_s": 1.0,
                                "tp": tp,
                                "precision": precision,
                                "query": query,
                                "component_params_file": f"components/{component}",
                                "component_params_sha256": v.digest(b"synthetic component\n"),
                                "counts": {
                                    "matrix_ops": 8.0,
                                    "memory_read_bytes": 16.0,
                                    "memory_write_bytes": None
                                    if query["phase"] == "decode"
                                    else 8.0,
                                },
                            }
                        )
    files["parity/fixtures.json"] = v.canonical(rows)
    files["parity/refusals.json"] = v.canonical(
        [
            {
                "component_params_file": "components/asic_placeholder.yaml",
                "compute": p,
                "kv_cache": p,
                "exception": "UnsupportedPrecision",
                "message": "synthetic refusal",
            }
            for p in ("bf16", "fp8")
        ]
    )
    from importlib.metadata import version

    files["uv.lock"] = (
        "\n".join(
            f'[[package]]\nname = "{name}"\nversion = "{version(name)}"'
            for name in ("pydantic", "pydantic-core")
        )
        + "\n"
    ).encode()
    from importlib.metadata import version

    files["GENERATOR.json"] = v.canonical(
        {
            "script_sha256": v.digest(Path(v.__file__).read_bytes()),
            "oracle_program_sha256": v.digest(v.ORACLE_PROGRAM.encode()),
            "rk_sha": v.PIN,
            "counts_scope": "replica",
            "duration_scope": "one_tp_rank_no_collectives",
            "environment": {
                "python_version": "3.12.0",
                "implementation": "CPython",
                "uv_lock_sha256": v.digest(files["uv.lock"]),
                "packages": {
                    "pydantic": version("pydantic"),
                    "pydantic-core": version("pydantic-core"),
                },
            },
        }
    )
    v.publish_snapshot(root, v.snapshot_bytes(files, v.PIN))
    return root


def mutate_synthetic(root: Path, name: str, data: bytes) -> None:
    """Rehash synthetic corruption to distinguish integrity from compatibility."""
    target = root / name
    target.parent.mkdir(parents=True, exist_ok=True)
    if target.exists():
        target.chmod(0o644)
    target.write_bytes(data)
    manifest = root / "MANIFEST.json"
    inventory = json.loads(manifest.read_text())
    inventory["files"][name] = v.digest(data)
    manifest.chmod(0o644)
    manifest.write_bytes(v.canonical(inventory))


@pytest.mark.parametrize(
    "field,value",
    [
        ("rk_sha", "c" * 40),
        ("counts_scope", "per_rank"),
        ("oracle_program_sha256", "0" * 64),
        ("script_sha256", "0" * 64),
        ("extra", "unknown"),
    ],
)
def test_f3_metadata_tampering_is_not_manifest_integrity(
    tmp_path: Path,
    field: str,
    value: str,
) -> None:
    root = synthetic_snapshot(tmp_path / "snapshot")
    v.check_generator(root)
    metadata = json.loads((root / "GENERATOR.json").read_text())
    metadata[field] = value
    mutate_synthetic(root, "GENERATOR.json", v.canonical(metadata))
    v.check_manifest(root)  # attacker-rehashed bytes are internally consistent
    with pytest.raises(ValueError, match="GENERATOR|generator|oracle"):
        v.check_generator(root)


def test_f3_program_drift_fails_current_but_preserves_historical_identity(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    root = synthetic_snapshot(tmp_path / "snapshot")
    v.check_generator(root)
    monkeypatch.setattr(v, "ORACLE_PROGRAM", v.ORACLE_PROGRAM + "\n# drift\n")
    v.check_generator(root, current=False)
    with pytest.raises(ValueError, match="oracle"):
        v.check_generator(root)


