@pytest.mark.parametrize("flag", ["--skip-worktree", "--assume-unchanged", "ignored"])
def test_f6_real_index_flags_and_ignored_shadow_refused(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    flag: str,
) -> None:
    subprocess.run(["git", "init", "-q", str(tmp_path)], check=True)
    (tmp_path / "tracked.py").write_text("ORIGINAL = 1\n")
    subprocess.run(["git", "-C", str(tmp_path), "add", "tracked.py"], check=True)
    if flag == "ignored":
        (tmp_path / ".git/info/exclude").write_text("shadow.py\n")
        (tmp_path / "shadow.py").write_text("import os\n")
    else:
        subprocess.run(["git", "-C", str(tmp_path), "update-index", flag, "tracked.py"], check=True)
        (tmp_path / "tracked.py").write_text("MODIFIED = 2\n")
    real_git = v.git

    def repo_git(root: Path, *args: str) -> str:
        # No synthetic commit is needed. Simulate a clean HEAD/status; inspect the real index.
        if args == ("rev-parse", "HEAD"):
            return v.PIN
        if args[0] == "status":
            return ""
        return real_git(root, *args)

    monkeypatch.setattr(v, "git", repo_git)
    with pytest.raises(ValueError, match="flags|ignored"):
        v.check_clone(tmp_path, v.PIN)


