def test_f7_locked_environment_is_checked_before_execution(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    calls = []

    def refuse(command: list[str], **kwargs: Any) -> Any:
        calls.append(command)
        assert command[:2] == ["uv", "sync"]
        assert {"--check", "--locked", "--offline"} <= set(command)
        raise subprocess.CalledProcessError(1, command, stderr="would change dependencies")

    monkeypatch.setattr(subprocess, "run", refuse)
    with pytest.raises(ValueError, match="environment"):
        v.verify_oracle_environment(tmp_path, {})
    assert len(calls) == 1


