def test_f1_boundaries_and_four_reported_quantities() -> None:
    import math

    from .parity import Deviation, compare_counts

    ds = [
        Deviation("a", "matrix_ops", 0.03, "term a"),
        Deviation("b", "matrix_ops", 0.02, "term b"),
    ]
    assert compare_counts("boundary", {"matrix_ops": 105.5}, {"matrix_ops": 100.0}, ds) == 0.055
    with pytest.raises(AssertionError):
        compare_counts(
            "outside", {"matrix_ops": math.nextafter(105.5, math.inf)}, {"matrix_ops": 100.0}, ds
        )
    with pytest.raises(ValueError):
        compare_counts(
            "overbudget",
            {"matrix_ops": 105.0},
            {"matrix_ops": 100.0},
            [*ds, Deviation("c", "matrix_ops", 1e-9, "over budget")],
        )
    row = sample()
    counts = rank_counts(row) | {"matrix_ops": 105.5}
    report = run_parity([row], lambda *args: counts, deviations={row["id"]: ds})
    result = report["comparisons"][row["id"]]["matrix_ops"]
    assert result["raw_rel"] == 0.055
    assert result["signed_adjustment_rel"] == 0.05
    assert result["absolute_adjustment_rel"] == 0.05
    assert result["residual_rel"] == pytest.approx(0.005)
    # Opposing legitimate terms spend absolute budget, not just the net adjustment.
    cancelling = [
        Deviation("a", "matrix_ops", 0.03, "addition"),
        Deviation("b", "matrix_ops", -0.02, "omission"),
    ]
    compare_counts("bounded cancellation", {"matrix_ops": 101.0}, {"matrix_ops": 100.0}, cancelling)


