@pytest.mark.parametrize("mode", [0o444, 0o644])
def test_f14_modes_do_not_replace_integrity_checks(tmp_path: Path, mode: int) -> None:
    root = tmp_path / "snapshot"
    v.publish_snapshot(root, v.snapshot_bytes({"synthetic.json": b"{}"}, v.PIN))
    for path in root.iterdir():
        path.chmod(mode)
    v.check_manifest(root)
    leaf = root / "synthetic.json"
    leaf.chmod(0o644)
    leaf.write_bytes(b"[]")
    leaf.chmod(mode)
    with pytest.raises(ValueError, match="MANIFEST mismatch"):
        v.check_manifest(root)


