def test_f9_nominal_parameter_offsets_are_recorded_without_correction(
    lane_a: dict[str, Any],
) -> None:
    record = json.loads((v.ROOT / "docs/reviews/U1-U-P2-nominal-parameters.json").read_text())
    assert record["denominator"] == "shape_implied"
    assert record["difference"] == "nominal_minus_shape_implied"
    assert record["automatic_adjustment"] is False
    model_shape = lane_a["model_shape"]
    for entry in record["models"]:
        sidecar = json.loads(
            (v.ROOT / "contract/fixtures/model_shapes" / (entry["id"] + ".json")).read_text()
        )
        model = model_shape.ModelSpec.model_validate(sidecar["model"])
        shape = model_shape.ModelShape.model_validate(sidecar["shape"])
        model_shape.check_parity(model, shape)  # existing rule, no new threshold
        implied = model_shape.implied_params(model, shape)
        for i, name in enumerate(("total_params", "active_params")):
            values = entry[name]
            assert values["nominal"] == getattr(model, name)
            assert values["shape_implied"] == implied[i]
            assert values["signed_difference"] == values["nominal"] - implied[i]
            assert values["relative_difference"] == values["signed_difference"] / implied[i]


@pytest.mark.parametrize("mutation", ["missing", "version", "lock", "packages"])
def test_f7_environment_tampering_is_refused(tmp_path: Path, mutation: str) -> None:
    root = synthetic_snapshot(tmp_path / "snapshot")
    data = json.loads((root / "GENERATOR.json").read_text())
    env = data["environment"]
    if mutation == "missing":
        del env["python_version"]
    elif mutation == "version":
        env["python_version"] = "unknown"
    elif mutation == "lock":
        env["uv_lock_sha256"] = "0" * 64
    else:
        env["packages"]["pydantic"] = "0.0.0"
    mutate_synthetic(root, "GENERATOR.json", v.canonical(data))
    v.check_manifest(root)
    with pytest.raises(ValueError, match="environment"):
        v.check_generator(root)


def test_f7_ci_runtime_need_not_equal_oracle_runtime(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    root = synthetic_snapshot(tmp_path / "snapshot")
    data = json.loads((root / "GENERATOR.json").read_text())
    lock = (
        b'[[package]]\nname="pydantic"\nversion="2.12.0"\n'
        b'[[package]]\nname="pydantic-core"\nversion="2.41.1"\n'
    )
    data["environment"]["packages"] = {"pydantic": "2.12.0", "pydantic-core": "2.41.1"}
    data["environment"]["uv_lock_sha256"] = v.digest(lock)
    monkeypatch.setattr(v, "PINNED_UV_LOCK_SHA256", v.digest(lock))
    mutate_synthetic(root, "uv.lock", lock)
    mutate_synthetic(root, "GENERATOR.json", v.canonical(data))
    v.check_generator(root)  # recorded lock-consistent runtime, independent of this process


