def test_f1_negative_boundary_and_unadjusted_boundary() -> None:
    import math

    from .parity import Deviation, compare_counts

    ds = [Deviation("minus", "matrix_ops", -0.05, "omitted operator")]
    assert compare_counts("negative", {"matrix_ops": 94.5}, {"matrix_ops": 100.0}, ds) == 0.055
    with pytest.raises(AssertionError):
        compare_counts(
            "outside", {"matrix_ops": math.nextafter(94.5, 0.0)}, {"matrix_ops": 100.0}, ds
        )
    assert compare_counts("raw", {"matrix_ops": 100.5}, {"matrix_ops": 100.0}) == 0.005
    with pytest.raises(AssertionError):
        compare_counts(
            "raw outside", {"matrix_ops": math.nextafter(100.5, 200.0)}, {"matrix_ops": 100.0}
        )
